/** Selection sort; O(n^2) time and O(1) extra space. */
import java.util.*;
public class SelectionSort {static void sort(int[]a){for(int i=0;i<a.length;i++){int min=i;for(int j=i+1;j<a.length;j++)if(a[j]<a[min])min=j;int t=a[i];a[i]=a[min];a[min]=t;}}public static void main(String[]args){Scanner sc=new Scanner(System.in);System.out.print("Array size: ");int n=sc.nextInt();if(n<0){System.out.println("Invalid size");sc.close();return;}int[]a=new int[n];System.out.println("Enter elements:");for(int i=0;i<n;i++)a[i]=sc.nextInt();sort(a);System.out.println(Arrays.toString(a));sc.close();}}